        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<DistributedSystemModel> create)
        {
            Load(ctx); DistributedSystemModel exact = Store.Models.FirstOrDefault(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId) && Eq(x.SourceFingerprint, fingerprint)); if (exact != null) { OpenModel(owner, ctx, index, exact); return; }
            DistributedSystemModel prior = Store.Models.FirstOrDefault(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)); DistributedSystemModel model = create == null ? StarterConstellation(sourceKind + " projection", "Typed distributed-systems projection.") : create(); model.Id = Id("distributed-model"); model.SourceKind = sourceKind; model.SourceId = sourceId; model.SourceFingerprint = fingerprint; model.ParentModelId = prior == null ? null : prior.Id; model.CreatedUtc = model.UpdatedUtc = Now(); if (prior != null) model.Name += " · source drift fork"; Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, prior == null ? "PROJECTION_CREATED" : "SOURCE_DRIFT_FORKED", model.Id, sourceKind + "/" + sourceId, DistributedSystemsKernel.Fingerprint(model), fingerprint); OpenModel(owner, ctx, index, model);
        }

        private static void OpenHub(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            Window w = W(owner, "YOMI · DISTRIBUTED SYSTEMS PLANETARIUM", 1510, 930); DockPanel root = Shell("DISTRIBUTED SYSTEMS PLANETARIUM / NETWORKED COMPUTATION CIVILIZATION", "Servers, processes, messages, clocks, elections, replicated logs, quorums, consistency, partitions, transactions, leases, gossip, failure detection, chaos and recovery—inside deterministic synthetic universes.");
            StackPanel status = new StackPanel { Margin = new Thickness(0, 2, 0, 12) }; status.Children.Add(T(Summary(), 12, Blue, FontWeights.SemiBold)); status.Children.Add(T("SIMULATION-ONLY AUTHORITY · No host, process, packet, port, secret, cloud, database, cluster or production system is discovered, contacted, modified or controlled.", 11.5, Amber, FontWeights.SemiBold)); DockPanel.SetDock(status, Dock.Top); root.Children.Add(status);
            WrapPanel chambers = new WrapPanel();
            Portal(chambers, "DISTΩ", "CONSTELLATION REGISTRY", "Open, fork and descend through persistent networked worlds with source lineage and content fingerprints.", delegate { OpenModels(w, ctx, index); });
            Portal(chambers, "SECΩ", "ADVERSARIAL SECURITY FORTRESS", "Project nodes, processes, replicas, messages and fault domains into a defensive security world with no live-system authority.", delegate { DistributedSystemModel m = ChooseModel(w); if (m != null) AdversarialSecurityFortress.OpenFromDistributedSystem(w, ctx, index, m); });
            Portal(chambers, "DATAΩ", "DATA FOUNDRY", "Project nodes, processes, replicas, clocks and fault-world metadata into lineage-aware structured evidence.", delegate { DistributedSystemModel m = ChooseModel(w); if (m != null) DataFoundry.OpenFromDistributedSystem(w, ctx, index, m); });
            Portal(chambers, "GENOMEΩ", "SOFTWARE GENOME", "Project distributed topology into source-level service and dependency analysis.", delegate { DistributedSystemModel m = ChooseModel(w); if (m != null) SoftwareGenomeObservatory.OpenFromDistributedSystem(w, ctx, index, m); });
            Portal(chambers, "DOCΩ", "LIVING DOCUMENT", "Project topology, consistency, failure and recovery evidence into an operability or architecture dossier.", delegate { DistributedSystemModel m = ChooseModel(w); if (m != null) LivingDocumentIntelligenceFactory.OpenFromDistributedSystem(w, ctx, index, m); });
            Portal(chambers, "EXPΩ", "EXPEDITION COMMAND", "Capture the active distributed-system model as a fingerprinted mission crossing with topology, consistency and failure evidence retained.", delegate { DistributedSystemModel m = ChooseModel(w); if (m != null) GrandUnifiedExpeditionCommand.OpenFromDistributedSystem(w, ctx, index, m); });
            Portal(chambers, "FORGE", "SYSTEM CONSTELLATION FORGE", "Create regions, zones, nodes, services, links, datasets, shards, replicas, workloads and failure scenarios.", delegate { CreateModel(w, ctx, index); });
            Portal(chambers, "DOM", "FAULT-DOMAIN GALAXY", "Regions, availability zones, racks, correlated failure boundaries and replica concentration.", delegate { OpenCollection(w, "FAULT DOMAINS", Store.Models.SelectMany(x => x.FaultDomains).Cast<object>().ToList(), "Failure independence is explicitly declared, never inferred from labels alone."); });
            Portal(chambers, "NODE", "NODE & PROCESS ORBITAL", "Hosts, capacities, clocks, services, roles, terms, epochs, health and restart policy.", delegate { OpenNodesAndProcesses(w); });
