        private static void EditModel(Window owner, DeepSystemsContext ctx, WorldIndex index) { DistributedSystemModel m = ChooseModel(owner); if (m == null) return; string kind = Prompt(owner, "CONSTRUCTION YARD", "ADD NODE | PROCESS | LINK | OPERATION | FAULT | SCENARIO", "NODE"); if (kind == null) return; if (Eq(kind.Trim(), "NODE")) AddNode(owner, ctx, m); else if (Eq(kind.Trim(), "PROCESS")) AddProcess(owner, ctx, m); else if (Eq(kind.Trim(), "LINK")) AddLink(owner, ctx, m); else if (Eq(kind.Trim(), "OPERATION")) AddOperation(owner, ctx, m); else if (Eq(kind.Trim(), "FAULT")) AddFault(owner, ctx, m); else if (Eq(kind.Trim(), "SCENARIO")) AddScenario(owner, ctx, m); else MessageBox.Show(owner, "Unknown construction kind.", "YOMI · CONSTRUCTION YARD", MessageBoxButton.OK, MessageBoxImage.Information); OpenModel(owner, ctx, index, m); }
        private static void AddNode(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD NODE", "id | name | region | zone | domain_id | clock_offset_ms | clock_drift_ppm", "node-new|New Node|us-central|zone-a|domain-a|0|0"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 5) return; m.Nodes.Add(new DistributedNode { Id = Key(f[0]), Name = f[1], Region = f[2], Zone = f[3], FaultDomainId = f[4], ClockOffsetMs = Number(f.Length > 5 ? f[5] : "", 0), ClockDriftPpm = Number(f.Length > 6 ? f[6] : "", 0) }); Mutated(ctx, m, "NODE_ADDED", f[0]); }
        private static void AddProcess(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD PROCESS", "id | name | service | node_id | group_id | voting", "proc-new|New Replica|ledger|node-new|ledger-group|true"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 5) return; m.Processes.Add(new DistributedProcess { Id = Key(f[0]), Name = f[1], Service = f[2], NodeId = f[3], GroupId = f[4], Voting = Bool(f.Length > 5 ? f[5] : "", true) }); Mutated(ctx, m, "PROCESS_ADDED", f[0]); }
        private static void AddLink(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD LINK", "id | from_node | to_node | bidirectional | latency_ms | jitter_ms | bandwidth_mbps | loss", "link-new|node-a|node-b|true|10|2|1000|0.001"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 4) return; m.Links.Add(new DistributedLink { Id = Key(f[0]), FromNodeId = f[1], ToNodeId = f[2], Bidirectional = Bool(f[3], true), BaseLatencyMs = Number(f.Length > 4 ? f[4] : "", 10), JitterMs = Number(f.Length > 5 ? f[5] : "", 2), BandwidthMbps = Number(f.Length > 6 ? f[6] : "", 1000), LossProbability = Number(f.Length > 7 ? f[7] : "", 0) }); Mutated(ctx, m, "LINK_ADDED", f[0]); }
        private static void AddOperation(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD OPERATION", "id | client | dataset | shard | kind | key | value | at_ms | deadline_ms", "op-new|client-a|ledger|ledger-0|WRITE|key|value|1000|2000"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 7) return; m.Workload.Add(new DistributedWorkloadOperation { Id = Key(f[0]), ClientId = f[1], DatasetId = f[2], ShardId = f[3], Kind = f[4].ToUpperInvariant(), Key = f[5], Value = f[6], AtMs = Number(f.Length > 7 ? f[7] : "", 0), DeadlineMs = Number(f.Length > 8 ? f[8] : "", 2000), CorrelationId = Id("corr") }); Mutated(ctx, m, "OPERATION_ADDED", f[0]); }
        private static void AddFault(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD FAULT", "id | name | kind | target | second_target | start_ms | duration_ms | magnitude", "fault-new|Synthetic failure|NODE_CRASH|node-a||10000|10000|1"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 4) return; m.Faults.Add(new DistributedFault { Id = Key(f[0]), Name = f[1], Kind = f[2].ToUpperInvariant(), TargetId = f[3], SecondaryTargetId = f.Length > 4 ? f[4] : null, StartMs = Number(f.Length > 5 ? f[5] : "", 10000), DurationMs = Number(f.Length > 6 ? f[6] : "", 10000), Magnitude = Number(f.Length > 7 ? f[7] : "", 1) }); Mutated(ctx, m, "FAULT_ADDED", f[0]); }
        private static void AddScenario(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string raw = Prompt(owner, "ADD SCENARIO", "id | name | duration_ms | max_events | latency_multiplier | loss_addition | fault_ids", "scenario-new|Failure world|60000|50000|1|0|fault-new"); if (raw == null) return; string[] f = Fields(raw); if (f.Length < 2) return; m.Scenarios.Add(new DistributedScenario { Id = Key(f[0]), Name = f[1], DurationMs = Number(f.Length > 2 ? f[2] : "", 60000), MaxEvents = Integer(f.Length > 3 ? f[3] : "", 50000, 100, 250000), LatencyMultiplier = Number(f.Length > 4 ? f[4] : "", 1), LossAddition = Number(f.Length > 5 ? f[5] : "", 0), EnabledFaultIds = f.Length > 6 ? f[6] : "" }); Mutated(ctx, m, "SCENARIO_ADDED", f[0]); }
        private static void Mutated(DeepSystemsContext ctx, DistributedSystemModel m, string evt, string subject) { m.Revision = Math.Max(1, m.Revision) + 1; m.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, evt, subject, m.Id, DistributedSystemsKernel.Fingerprint(m), ""); }

        private static void ForkModel(Window owner, DeepSystemsContext ctx, WorldIndex index) { DistributedSystemModel m = ChooseModel(owner); if (m != null) ForkModelFor(owner, ctx, index, m); }
        private static void ForkModelFor(Window owner, DeepSystemsContext ctx, WorldIndex index, DistributedSystemModel source) { string name = Prompt(owner, "PARALLEL UNIVERSE", "Fork name", (source.Name ?? source.Id) + " · counterfactual"); if (name == null) return; DistributedSystemModel fork = Json.Deserialize<DistributedSystemModel>(Json.Serialize(source)); fork.Id = Id("distributed-model"); fork.ParentModelId = source.Id; fork.Name = Short(name, MaxShortText); fork.Revision = 1; fork.CreatedUtc = fork.UpdatedUtc = Now(); Store.Models.Insert(0, fork); Save(ctx); AppendLedger(ctx, "CONSTELLATION_FORKED", fork.Id, "parent=" + source.Id, DistributedSystemsKernel.Fingerprint(fork), DistributedSystemsKernel.Fingerprint(source)); OpenModel(owner, ctx, index, fork); }

        private static void CreateCapsule(Window owner, DeepSystemsContext ctx) { DistributedSystemModel m = ChooseModel(owner); if (m == null) return; string title = Prompt(owner, "CHAOS PREREGISTRATION", "Expedition title", "Distributed resilience expedition · " + (m.Name ?? m.Id)); if (title == null) return; string question = PromptLarge(owner, "CHAOS PREREGISTRATION", "Question and hypothesis", "Question: Does the declared quorum remain available and safe through the selected fault world?\nHypothesis: The bounded trace preserves safety invariants and recovers inside the declared RTO."); if (question == null) return; DistributedScenario s = ChooseOptionalScenario(owner, m); DistributedExpeditionCapsule c = new DistributedExpeditionCapsule { Id = Id("distributed-capsule"), ModelId = m.Id, Title = Short(title, MaxShortText), Question = Short(question, MaxLongText), Hypothesis = "Bounded safety and recovery claim retained before execution.", ScenarioId = s == null ? "BASE" : s.Id, FrozenUtc = Now(), ModelFingerprint = DistributedSystemsKernel.Fingerprint(m), DurationMs = s == null ? 60000 : s.DurationMs, EventLimit = s == null ? 50000 : s.MaxEvents, FrozenParameters = new Dictionary<string, double>(m.Parameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase), Invariants = new List<string> { "At most one leader per term.", "Applied index never exceeds commit index; commit never exceeds log index.", "Acknowledged writes remain represented by a surviving committed replica inside the trace.", "Fencing tokens increase monotonically." }, Assumptions = new List<string>(m.Assumptions ?? new List<string>()), EvidenceNodeIds = m.EvidenceNodeIds.Take(MaxEvidence).ToList() }; c.CertificateHash = HashText(Json.Serialize(c)); Store.Capsules.Insert(0, c); Save(ctx); AppendLedger(ctx, "EXPEDITION_PREREGISTERED", c.Id, c.Title, c.ModelFingerprint, c.CertificateHash); OpenCollection(owner, "CHAOS PREREGISTRATION", new List<object> { c, c.Question, c.Hypothesis, c.AcceptanceRule, c.AuthorityBoundary }.Concat(c.Invariants).Concat(c.Assumptions).ToList(), "Frozen before execution; edits require a new capsule."); }
        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx) { DistributedSystemModel m = ChooseModel(owner); if (m != null) FreezeBaselineFor(owner, ctx, m); }
        private static void FreezeBaselineFor(Window owner, DeepSystemsContext ctx, DistributedSystemModel m) { string reason = PromptLarge(owner, "FREEZE BASELINE", "Reason for immutable configuration snapshot", "Network configuration checkpoint before chaos descent."); if (reason == null) return; string snapshot = Json.Serialize(m); DistributedSystemBaseline prior = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, m.Id)); DistributedSystemBaseline b = new DistributedSystemBaseline { Id = Id("distributed-baseline"), ModelId = m.Id, ParentBaselineId = prior == null ? null : prior.Id, Name = (m.Name ?? m.Id) + " · baseline", Reason = Short(reason, MaxLongText), Status = "FROZEN", FrozenUtc = Now(), ModelFingerprint = DistributedSystemsKernel.Fingerprint(m), SnapshotJson = snapshot, BaselineFingerprint = HashText(snapshot) }; Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", b.Id, b.Reason, b.ModelFingerprint, b.BaselineFingerprint); OpenCollection(owner, "DISTRIBUTED BASELINE", new List<object> { b }, "Immutable serialized constellation snapshot."); }
        private static void CreateDossier(Window owner, DeepSystemsContext ctx) { DistributedSystemModel m = ChooseModel(owner); if (m == null) return; string title = Prompt(owner, "RESILIENCE DOSSIER", "Dossier title", "Distributed resilience dossier · " + (m.Name ?? m.Id)); if (title == null) return; DistributedDecisionDossier d = new DistributedDecisionDossier { Id = Id("distributed-dossier"), ModelId = m.Id, Title = Short(title, MaxShortText), CreatedUtc = Now(), UpdatedUtc = Now(), ModelFingerprint = DistributedSystemsKernel.Fingerprint(m), SimulationId = FirstId(Store.Simulations, m.Id, x => x.ModelId, x => x.Id), TopologyId = FirstId(Store.Topologies, m.Id, x => x.ModelId, x => x.Id), QuorumId = FirstId(Store.Quorums, m.Id, x => x.ModelId, x => x.Id), GossipId = FirstId(Store.GossipRuns, m.Id, x => x.ModelId, x => x.Id), TransactionId = FirstId(Store.Transactions, m.Id, x => x.ModelId, x => x.Id), LeaseId = FirstId(Store.Leases, m.Id, x => x.ModelId, x => x.Id), ChaosId = FirstId(Store.ChaosCampaigns, m.Id, x => x.ModelId, x => x.Id), BaselineId = FirstId(Store.Baselines, m.Id, x => x.ModelId, x => x.Id), CapsuleId = FirstId(Store.Capsules, m.Id, x => x.ModelId, x => x.Id), BoundedInterpretation = "This dossier binds retained synthetic configuration and computation certificates; it does not establish production behavior or implementation correctness.", SafetyClaims = new List<string> { "Inspect one-leader-per-term, log-index order, quorum intersection and fencing witnesses independently." }, LivenessClaims = new List<string> { "Recovery and election completion are bounded by the explored horizon and message schedule." }, ConsistencyConditions = new List<string> { "Consistency depends on per-operation routing, quorum, session history and surviving replica state." }, RecoveryConditions = new List<string> { "RTO/RPO evidence is valid only for declared faults, timeouts, capacities and workloads." }, Alternatives = new List<string> { "Retain a simpler fail-stop architecture and a degraded read-only mode as explicit alternatives." }, Unknowns = new List<string> { "Implementation defects, kernel scheduling, real clock behavior, queueing, saturation, correlated infrastructure and operator action remain unresolved." }, Dissent = new List<string> { "A successful bounded simulation is not a proof that every admissible execution is safe or live." }, EvidenceNodeIds = m.EvidenceNodeIds.Take(MaxEvidence).ToList() }; Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Title, d.ModelFingerprint, HashText(Json.Serialize(d))); OpenCollection(owner, "RESILIENCE DOSSIER", new List<object> { d, d.BoundedInterpretation, d.AuthorityBoundary }.Concat(d.SafetyClaims).Concat(d.LivenessClaims).Concat(d.ConsistencyConditions).Concat(d.RecoveryConditions).Concat(d.Alternatives).Concat(d.Unknowns).Concat(d.Dissent).Cast<object>().ToList(), "Evidence-bound interpretation with dissent intact."); }

