        private static void OpenHadal(Window owner, DeepSystemsContext ctx, WorldIndex index) { DistributedSystemModel m = ChooseModel(owner); if (m == null) return; List<object> choices = new List<object> { m }; choices.AddRange(m.Nodes.Cast<object>()); choices.AddRange(m.Processes.Cast<object>()); choices.AddRange(m.Links.Cast<object>()); choices.AddRange(m.Datasets.Cast<object>()); choices.AddRange(m.Replicas.Cast<object>()); choices.AddRange(m.Faults.Cast<object>()); object subject = ChooseObject(owner, "HADAL SUBJECT", "Choose a system object for recursive descent.", choices); if (subject == null) return; List<object> rows = new List<object> { subject, "MODEL FINGERPRINT · " + DistributedSystemsKernel.Fingerprint(m), "SOURCE · " + (m.SourceKind ?? "NATIVE") + "/" + (m.SourceId ?? "∅"), "SOURCE FINGERPRINT · " + (m.SourceFingerprint ?? "∅"), "PARENT MODEL · " + (m.ParentModelId ?? "∅") }; string id = SubjectId(subject); rows.AddRange(Related(m, id)); rows.AddRange(Evidence(subject).Take(MaxEvidence).Select(x => (object)("EVIDENCE · " + x))); rows.AddRange(Store.Simulations.Where(x => Eq(x.ModelId, m.Id)).Take(16).Cast<object>()); rows.AddRange(Store.ChaosCampaigns.Where(x => Eq(x.ModelId, m.Id)).Take(16).Cast<object>()); OpenCollection(owner, "HADAL PROTOCOL DESCENT", rows, "Object → placement → channel → replica → workload → fault → trace → evidence without flattening provenance."); }
