        private static DistributedSystemModel StarterConstellation(string name, string description)
        {
            string now = Now(); DistributedSystemModel m = new DistributedSystemModel { Id = Id("distributed-model"), Name = name, Description = description, CreatedUtc = now, UpdatedUtc = now, SourceKind = "NATIVE", ProtocolFamily = "RAFT_LIKE" }; m.Parameters["heartbeat_ms"] = 750; m.Parameters["election_min_ms"] = 1800; m.Parameters["election_max_ms"] = 3400; m.Parameters["rto_target_ms"] = 15000; m.Parameters["rpo_target_ms"] = 0; m.Parameters["p95_target_ms"] = 250; m.Parameters["phi_threshold"] = 8; m.Parameters["snapshot_threshold_entries"] = 10000; m.Parameters["anti_entropy_interval_ms"] = 5000;
            m.FaultDomains.AddRange(new[] { new DistributedFaultDomain { Id = "region-sol", Name = "Sol Region", Kind = "REGION", Region = "sol" }, new DistributedFaultDomain { Id = "region-vulcan", Name = "Vulcan Region", Kind = "REGION", Region = "vulcan" }, new DistributedFaultDomain { Id = "region-delta", Name = "Delta Region", Kind = "REGION", Region = "delta" }, new DistributedFaultDomain { Id = "sol-a", Name = "Sol A", Kind = "ZONE", ParentId = "region-sol", Region = "sol", Correlation = 0.05 }, new DistributedFaultDomain { Id = "sol-b", Name = "Sol B", Kind = "ZONE", ParentId = "region-sol", Region = "sol", Correlation = 0.05 }, new DistributedFaultDomain { Id = "vulcan-a", Name = "Vulcan A", Kind = "ZONE", ParentId = "region-vulcan", Region = "vulcan", Correlation = 0.04 }, new DistributedFaultDomain { Id = "vulcan-b", Name = "Vulcan B", Kind = "ZONE", ParentId = "region-vulcan", Region = "vulcan", Correlation = 0.04 }, new DistributedFaultDomain { Id = "delta-a", Name = "Delta A", Kind = "ZONE", ParentId = "region-delta", Region = "delta", Correlation = 0.06 } });
            AddNodeSeed(m, "node-sol-a1", "Sol A / Alpha", "sol-a", "sol", "a", "rack-1", 0.3, 2.1); AddNodeSeed(m, "node-sol-b1", "Sol B / Beta", "sol-b", "sol", "b", "rack-2", -0.5, -1.2); AddNodeSeed(m, "node-vulcan-a1", "Vulcan A / Logic", "vulcan-a", "vulcan", "a", "rack-1", 1.1, 0.4); AddNodeSeed(m, "node-vulcan-b1", "Vulcan B / Science", "vulcan-b", "vulcan", "b", "rack-4", -1.4, 1.8); AddNodeSeed(m, "node-delta-a1", "Delta A / Relay", "delta-a", "delta", "a", "rack-8", 2.2, -0.7); AddNodeSeed(m, "node-edge-sol", "Sol Edge Gateway", "sol-a", "sol", "a", "edge", 0.2, 4.0); AddNodeSeed(m, "node-observer", "Independent Witness", "vulcan-b", "vulcan", "b", "witness", -0.8, 0.1);
            AddProcessSeed(m, "proc-ledger-1", "Ledger Replica 1", "ledger", "node-sol-a1", "ledger-group", "LEADER", true); AddProcessSeed(m, "proc-ledger-2", "Ledger Replica 2", "ledger", "node-sol-b1", "ledger-group", "FOLLOWER", true); AddProcessSeed(m, "proc-ledger-3", "Ledger Replica 3", "ledger", "node-vulcan-a1", "ledger-group", "FOLLOWER", true); AddProcessSeed(m, "proc-ledger-4", "Ledger Replica 4", "ledger", "node-vulcan-b1", "ledger-group", "FOLLOWER", true); AddProcessSeed(m, "proc-ledger-5", "Ledger Replica 5", "ledger", "node-delta-a1", "ledger-group", "FOLLOWER", true); AddProcessSeed(m, "proc-gateway", "Request Gateway", "gateway", "node-edge-sol", "gateway-group", "LEADER", false); AddProcessSeed(m, "proc-witness", "Independent Observer", "witness", "node-observer", "observer-group", "FOLLOWER", false);
            string[] nodeIds = m.Nodes.Select(x => x.Id).ToArray(); for (int i = 0; i < nodeIds.Length; i++) for (int j = i + 1; j < nodeIds.Length; j++) { DistributedNode a = m.Nodes.First(x => Eq(x.Id, nodeIds[i])), b = m.Nodes.First(x => Eq(x.Id, nodeIds[j])); bool sameRegion = Eq(a.Region, b.Region); m.Links.Add(new DistributedLink { Id = "link-" + i + "-" + j, FromNodeId = a.Id, ToNodeId = b.Id, Bidirectional = true, BaseLatencyMs = sameRegion ? 3 + (i + j) % 5 : 42 + (i * 17 + j * 11) % 55, JitterMs = sameRegion ? 1.5 : 12, BandwidthMbps = sameRegion ? 5000 : 1000, LossProbability = sameRegion ? 0.0001 : 0.002, DuplicationProbability = 0.0002, ReorderProbability = sameRegion ? 0.0005 : 0.004, Reliability = 0.9995 }); }
            m.Datasets.Add(new DistributedDataset { Id = "astra-ledger", Name = "Astra Mission Ledger", Kind = "ORDERED_LOG", ConsistencyModel = "LINEARIZABLE", ReplicationFactor = 5, ReadQuorum = 3, WriteQuorum = 3, ShardCount = 1, SynchronousCommit = true, RetentionSeconds = 31536000 }); m.Datasets.Add(new DistributedDataset { Id = "telemetry-cache", Name = "Telemetry Cache", Kind = "KEY_VALUE", ConsistencyModel = "CAUSAL_EVENTUAL", ReplicationFactor = 3, ReadQuorum = 1, WriteQuorum = 1, ShardCount = 2, SynchronousCommit = false, RetentionSeconds = 86400 });
            m.Shards.Add(new DistributedShard { Id = "astra-ledger-0", DatasetId = "astra-ledger", KeyRangeStart = "", KeyRangeEnd = "", LeaderReplicaId = "rep-ledger-1", Epoch = 1 }); m.Shards.Add(new DistributedShard { Id = "telemetry-a-m", DatasetId = "telemetry-cache", KeyRangeStart = "a", KeyRangeEnd = "n", LeaderReplicaId = "rep-telemetry-a1", Epoch = 1 }); m.Shards.Add(new DistributedShard { Id = "telemetry-n-z", DatasetId = "telemetry-cache", KeyRangeStart = "n", KeyRangeEnd = "{", LeaderReplicaId = "rep-telemetry-n1", Epoch = 1 });
            for (int i = 1; i <= 5; i++) { string process = "proc-ledger-" + i, node = m.Processes.First(x => Eq(x.Id, process)).NodeId; m.Replicas.Add(new DistributedReplica { Id = "rep-ledger-" + i, DatasetId = "astra-ledger", ShardId = "astra-ledger-0", NodeId = node, ProcessId = process, Role = i == 1 ? "LEADER" : "FOLLOWER", Term = 1, StateHash = "genesis-astra", VectorClock = process + "=0" }); }
            m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-a1", DatasetId = "telemetry-cache", ShardId = "telemetry-a-m", NodeId = "node-sol-a1", ProcessId = "proc-ledger-1", Role = "PRIMARY", StateHash = "genesis-telemetry-a" }); m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-a2", DatasetId = "telemetry-cache", ShardId = "telemetry-a-m", NodeId = "node-vulcan-a1", ProcessId = "proc-ledger-3", Role = "REPLICA", StateHash = "genesis-telemetry-a" }); m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-a3", DatasetId = "telemetry-cache", ShardId = "telemetry-a-m", NodeId = "node-delta-a1", ProcessId = "proc-ledger-5", Role = "REPLICA", StateHash = "genesis-telemetry-a" }); m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-n1", DatasetId = "telemetry-cache", ShardId = "telemetry-n-z", NodeId = "node-sol-b1", ProcessId = "proc-ledger-2", Role = "PRIMARY", StateHash = "genesis-telemetry-n" }); m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-n2", DatasetId = "telemetry-cache", ShardId = "telemetry-n-z", NodeId = "node-vulcan-b1", ProcessId = "proc-ledger-4", Role = "REPLICA", StateHash = "genesis-telemetry-n" }); m.Replicas.Add(new DistributedReplica { Id = "rep-telemetry-n3", DatasetId = "telemetry-cache", ShardId = "telemetry-n-z", NodeId = "node-delta-a1", ProcessId = "proc-ledger-5", Role = "REPLICA", StateHash = "genesis-telemetry-n" });
            for (int i = 0; i < 30; i++) m.Workload.Add(new DistributedWorkloadOperation { Id = "op-" + (i + 1).ToString("00", CultureInfo.InvariantCulture), ClientId = i % 2 == 0 ? "client-sol" : "client-vulcan", DatasetId = "astra-ledger", ShardId = "astra-ledger-0", Kind = i % 3 == 0 ? "WRITE" : "READ", Key = "mission-" + (i % 5), Value = "state-" + i, AtMs = 1000 + i * 1100, DeadlineMs = 2500, CorrelationId = "mission-flow-" + (i % 5) });
            m.Faults.AddRange(new[] { new DistributedFault { Id = "fault-leader-crash", Name = "Leader crash", Kind = "PROCESS_CRASH", TargetId = "proc-ledger-1", StartMs = 10000, DurationMs = 9000, Magnitude = 1 }, new DistributedFault { Id = "fault-sol-vulcan-partition", Name = "Sol/Vulcan partition", Kind = "PARTITION", TargetId = "node-sol-a1", SecondaryTargetId = "node-vulcan-a1", StartMs = 12000, DurationMs = 12000, Magnitude = 1 }, new DistributedFault { Id = "fault-asymmetric", Name = "Asymmetric relay cut", Kind = "ASYMMETRIC_PARTITION", TargetId = "node-delta-a1", SecondaryTargetId = "node-sol-b1", StartMs = 8000, DurationMs = 16000, Magnitude = 1 }, new DistributedFault { Id = "fault-clock-skew", Name = "Witness clock excursion", Kind = "CLOCK_SKEW", TargetId = "node-observer", StartMs = 6000, DurationMs = 18000, Magnitude = 750 }, new DistributedFault { Id = "fault-loss", Name = "Interregion packet loss", Kind = "PACKET_LOSS", TargetId = "*", StartMs = 5000, DurationMs = 20000, Magnitude = 0.15 }, new DistributedFault { Id = "fault-latency", Name = "Tail latency storm", Kind = "LATENCY_SPIKE", TargetId = "*", StartMs = 5000, DurationMs = 20000, Magnitude = 8 }, new DistributedFault { Id = "fault-disk", Name = "Replica disk failure", Kind = "DISK_FAILURE", TargetId = "node-sol-b1", StartMs = 9000, DurationMs = 22000, Magnitude = 1 } });
            m.Scenarios.AddRange(new[] { Scenario("nominal", "Nominal constellation", "", 1), Scenario("leader-crash", "Leader crash and recovery", "fault-leader-crash", 1), Scenario("region-partition", "Interregion partition", "fault-sol-vulcan-partition", 1), Scenario("asymmetric-partition", "Asymmetric reachability", "fault-asymmetric", 0.7), Scenario("clock-excursion", "Clock skew world", "fault-clock-skew", 0.6), Scenario("packet-loss", "Packet loss storm", "fault-loss", 0.8), Scenario("tail-latency", "Latency amplification", "fault-latency", 0.8), Scenario("disk-failure", "Durable replica loss", "fault-disk", 0.8), Scenario("compound-chaos", "Leader, packet and disk compound world", "fault-leader-crash,fault-loss,fault-disk", 0.4) });
            m.Assumptions.Add("All entities, clocks, packets, failures, storage states and workloads are synthetic and locally retained."); m.Assumptions.Add("The consensus engine is intentionally Raft-like and bounded; it is not a standards claim or implementation proof."); m.Assumptions.Add("Fault domains are independent only where explicitly declared; labels do not create real independence."); m.Assumptions.Add("No real network discovery, connection, process control, packet generation, credential use, database mutation or cloud action is authorized."); return m;
        }
        private static void AddNodeSeed(DistributedSystemModel m, string id, string name, string domain, string region, string zone, string rack, double offset, double drift) { m.Nodes.Add(new DistributedNode { Id = id, Name = name, FaultDomainId = domain, Region = region, Zone = zone, Rack = rack, CpuCores = 16, MemoryGb = 64, DiskGb = 2048, ClockOffsetMs = offset, ClockDriftPpm = drift, Reliability = 0.9995 }); }
        private static void AddProcessSeed(DistributedSystemModel m, string id, string name, string service, string node, string group, string role, bool voting) { m.Processes.Add(new DistributedProcess { Id = id, Name = name, Service = service, NodeId = node, GroupId = group, Role = role, Term = role == "LEADER" ? 1 : 0, Priority = 1, Voting = voting, AutoRestart = true, RestartDelayMs = 5000 }); }
        private static DistributedScenario Scenario(string id, string name, string faults, double weight) { return new DistributedScenario { Id = id, Name = name, EnabledFaultIds = faults, Weight = weight, DurationMs = 45000, MaxEvents = 50000, TrafficMultiplier = 1, LatencyMultiplier = 1, ClockSkewMultiplier = 1 }; }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<DistributedPlanetariumStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<DistributedPlanetariumStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new DistributedPlanetariumStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new DistributedPlanetariumStore(); if (Store.Models == null) Store.Models = new List<DistributedSystemModel>(); if (Store.Simulations == null) Store.Simulations = new List<DistributedSimulationArtifact>(); if (Store.Topologies == null) Store.Topologies = new List<DistributedTopologyArtifact>(); if (Store.Quorums == null) Store.Quorums = new List<DistributedQuorumArtifact>(); if (Store.GossipRuns == null) Store.GossipRuns = new List<DistributedGossipArtifact>(); if (Store.Transactions == null) Store.Transactions = new List<DistributedTransactionArtifact>(); if (Store.Leases == null) Store.Leases = new List<DistributedLeaseArtifact>(); if (Store.ChaosCampaigns == null) Store.ChaosCampaigns = new List<DistributedChaosArtifact>(); if (Store.Capsules == null) Store.Capsules = new List<DistributedExpeditionCapsule>(); if (Store.Baselines == null) Store.Baselines = new List<DistributedSystemBaseline>(); if (Store.Dossiers == null) Store.Dossiers = new List<DistributedDecisionDossier>(); foreach (DistributedSystemModel m in Store.Models.Where(x => x != null)) NormalizeModel(m); }
        private static void NormalizeModel(DistributedSystemModel m) { if (m.Parameters == null) m.Parameters = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); if (m.FaultDomains == null) m.FaultDomains = new List<DistributedFaultDomain>(); if (m.Nodes == null) m.Nodes = new List<DistributedNode>(); if (m.Processes == null) m.Processes = new List<DistributedProcess>(); if (m.Links == null) m.Links = new List<DistributedLink>(); if (m.Datasets == null) m.Datasets = new List<DistributedDataset>(); if (m.Shards == null) m.Shards = new List<DistributedShard>(); if (m.Replicas == null) m.Replicas = new List<DistributedReplica>(); if (m.Workload == null) m.Workload = new List<DistributedWorkloadOperation>(); if (m.Faults == null) m.Faults = new List<DistributedFault>(); if (m.Scenarios == null) m.Scenarios = new List<DistributedScenario>(); if (m.Assumptions == null) m.Assumptions = new List<string>(); if (m.EvidenceNodeIds == null) m.EvidenceNodeIds = new List<string>(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("distributed-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void TrimStore() { Store.Models = Store.Models.Where(x => x != null).Take(MaxModels).ToList(); Store.Simulations = Store.Simulations.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Topologies = Store.Topologies.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Quorums = Store.Quorums.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.GossipRuns = Store.GossipRuns.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Transactions = Store.Transactions.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Leases = Store.Leases.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.ChaosCampaigns = Store.ChaosCampaigns.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Capsules = Store.Capsules.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Baselines = Store.Baselines.Where(x => x != null).Take(MaxArtifacts).ToList(); Store.Dossiers = Store.Dossiers.Where(x => x != null).Take(MaxArtifacts).ToList(); }
        private static void AtomicWrite(string path, string text) { string temp = path + ".next"; string previous = path + ".previous"; File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { if (File.Exists(previous)) File.Delete(previous); File.Move(path, previous); } File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (File.Exists(path)) File.Copy(path, path + ".corrupt-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture), true); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "distributed-systems-planetarium-v1.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "distributed-systems-ledger-v1.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<DistributedLedgerRecord> prior = ReadLedger(ctx, 32768); DistributedLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); DistributedLedgerRecord r = new DistributedLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<DistributedLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<DistributedLedgerRecord> rows = new List<DistributedLedgerRecord>(); string path = LedgerPath(ctx); if (!File.Exists(path)) return rows; try { foreach (string line in File.ReadLines(path, Encoding.UTF8)) { if (String.IsNullOrWhiteSpace(line)) continue; DistributedLedgerRecord r = Json.Deserialize<DistributedLedgerRecord>(line); if (r != null) { rows.Add(r); if (rows.Count > cap) rows.RemoveAt(0); } } } catch { } return rows; }
        private static string VerifyLedger(List<DistributedLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY CHAIN"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (DistributedLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(DistributedLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static DistributedSystemModel ChooseModel(Window owner) { return ChooseObject(owner, "SELECT CONSTELLATION", "Choose an authoritative retained model.", Store.Models.Cast<object>().ToList()) as DistributedSystemModel; }
        private static DistributedScenario ChooseOptionalScenario(Window owner, DistributedSystemModel model) { if (model == null || model.Scenarios.Count == 0) return null; List<object> values = new List<object> { "BASE / NO FAULT WORLD" }; values.AddRange(model.Scenarios.Cast<object>()); return ChooseObject(owner, "SCENARIO WORLD", "Choose a scenario or the base world.", values) as DistributedScenario; }
        private static List<object> Related(DistributedSystemModel m, string id) { List<object> rows = new List<object>(); rows.AddRange(m.Nodes.Where(x => Eq(x.FaultDomainId, id)).Cast<object>()); rows.AddRange(m.Processes.Where(x => Eq(x.NodeId, id) || Eq(x.GroupId, id)).Cast<object>()); rows.AddRange(m.Links.Where(x => Eq(x.FromNodeId, id) || Eq(x.ToNodeId, id)).Cast<object>()); rows.AddRange(m.Shards.Where(x => Eq(x.DatasetId, id) || Eq(x.LeaderReplicaId, id)).Cast<object>()); rows.AddRange(m.Replicas.Where(x => Eq(x.DatasetId, id) || Eq(x.ShardId, id) || Eq(x.NodeId, id) || Eq(x.ProcessId, id)).Cast<object>()); rows.AddRange(m.Workload.Where(x => Eq(x.ClientId, id) || Eq(x.DatasetId, id) || Eq(x.ShardId, id)).Cast<object>()); rows.AddRange(m.Faults.Where(x => Eq(x.TargetId, id) || Eq(x.SecondaryTargetId, id)).Cast<object>()); return rows; }
        private static string SubjectId(object x) { DistributedSystemModel m = x as DistributedSystemModel; if (m != null) return m.Id; DistributedFaultDomain d = x as DistributedFaultDomain; if (d != null) return d.Id; DistributedNode n = x as DistributedNode; if (n != null) return n.Id; DistributedProcess p = x as DistributedProcess; if (p != null) return p.Id; DistributedLink l = x as DistributedLink; if (l != null) return l.Id; DistributedDataset s = x as DistributedDataset; if (s != null) return s.Id; DistributedReplica r = x as DistributedReplica; if (r != null) return r.Id; DistributedFault f = x as DistributedFault; return f == null ? "" : f.Id; }
        private static List<string> Evidence(object x) { DistributedSystemModel m = x as DistributedSystemModel; if (m != null) return m.EvidenceNodeIds; DistributedFaultDomain d = x as DistributedFaultDomain; if (d != null) return d.EvidenceNodeIds; DistributedNode n = x as DistributedNode; if (n != null) return n.EvidenceNodeIds; DistributedProcess p = x as DistributedProcess; if (p != null) return p.EvidenceNodeIds; DistributedLink l = x as DistributedLink; if (l != null) return l.EvidenceNodeIds; DistributedDataset s = x as DistributedDataset; return s == null ? new List<string>() : s.EvidenceNodeIds; }
        private static string Summary() { return Store.Models.Count + " constellations   ·   " + Store.Simulations.Count + " execution traces   ·   " + Store.Topologies.Count + " topology certificates   ·   " + Store.Quorums.Count + " quorum atlases   ·   " + Store.GossipRuns.Count + " gossip worlds   ·   " + Store.Transactions.Count + " transactions   ·   " + Store.Leases.Count + " leases   ·   " + Store.ChaosCampaigns.Count + " chaos campaigns   ·   " + Store.Capsules.Count + " preregistrations   ·   " + Store.Baselines.Count + " baselines   ·   " + Store.Dossiers.Count + " dossiers"; }
        private static string FirstId<T>(IEnumerable<T> rows, string modelId, Func<T, string> model, Func<T, string> id) { T value = (rows ?? Enumerable.Empty<T>()).FirstOrDefault(x => Eq(model(x), modelId)); return Object.Equals(value, default(T)) ? null : id(value); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Number(string raw, double fallback) { double v; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out v) && !Double.IsNaN(v) && !Double.IsInfinity(v) ? v : fallback; }
        private static int Integer(string raw, int fallback, int min, int max) { int v; if (!Int32.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out v)) v = fallback; return Math.Max(min, Math.Min(max, v)); }
        private static bool Bool(string raw, bool fallback) { bool v; return Boolean.TryParse(raw, out v) ? v : fallback; }
        private static string[] Fields(string raw) { return (raw ?? "").Split('|'); }
        private static List<string> Tokens(string raw) { return (raw ?? "").Split(new[] { ',', ';', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).ToList(); }
        private static string Key(string value) { StringBuilder s = new StringBuilder(); foreach (char c in (value ?? "").ToLowerInvariant()) if (Char.IsLetterOrDigit(c) || c == '_' || c == '-') s.Append(c); else if (s.Length > 0 && s[s.Length - 1] != '-') s.Append('-'); return s.ToString().Trim('-'); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(value ?? ""))).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 370, Height = 124, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 720, 300); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 820, 580); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { Window w = W(owner, "YOMI · " + title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenCollection(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1280, 840); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
        private static void OpenSelectable(Window owner, string title, IList<object> rows, string subtitle, Action<object> open) { Window w = W(owner, "YOMI · " + title, 1280, 840); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); list.MouseDoubleClick += delegate { if (list.SelectedItem != null && open != null) open(list.SelectedItem); }; root.Children.Add(list); w.Content = root; w.Show(); }
    }
